import{_ as s,C as a,o as l,c as n,j as t,a as c,G as i,a2 as d}from"./chunks/framework.BgSoyxN5.js";const b=JSON.parse('{"title":"TickerForge Features | Investing Decision Support Platform","description":"Analyze stocks, monitor watchlists, review portfolio fit, stress-test risk, and follow market regime shifts with TickerForge.","frontmatter":{"title":"TickerForge Features | Investing Decision Support Platform","description":"Analyze stocks, monitor watchlists, review portfolio fit, stress-test risk, and follow market regime shifts with TickerForge."},"headers":[],"relativePath":"features.md","filePath":"features.md","lastUpdated":1785682435000}'),h={name:"features.md"};function p(u,e,f,m,k,g){const r=a("TickerForgeComplianceDisclaimer"),o=a("TickerForgeTrustBlock");return l(),n("div",null,[e[0]||(e[0]=t("h1",{id:"features",tabindex:"-1"},[c("Features "),t("a",{class:"header-anchor",href:"#features","aria-label":'Permalink to "Features"'},"​")],-1)),e[1]||(e[1]=t("p",null,"TickerForge is an investing decision-support platform. It helps users organize public market data, analyze stocks, monitor watchlists, review portfolio health, track market regime context, and receive research notifications when selected indicators change.",-1)),i(r),i(o,{kind:"platform"}),e[2]||(e[2]=d('<h2 id="research-candidates" tabindex="-1">Research Candidates <a class="header-anchor" href="#research-candidates" aria-label="Permalink to &quot;Research Candidates&quot;">​</a></h2><p>Use TickerForge to surface companies worth a closer look:</p><ul><li>screen 3,000+ active stocks using fundamentals, valuation context, and quality indicators;</li><li>compare business quality, balance-sheet strength, and risk;</li><li>review Smart Money and insider activity reported through public filings;</li><li>track names where monitored indicators change.</li></ul><p>TickerForge is not built to provide trade instructions. It is built to help you decide what deserves deeper research.</p><h2 id="review-stock-context" tabindex="-1">Review Stock Context <a class="header-anchor" href="#review-stock-context" aria-label="Permalink to &quot;Review Stock Context&quot;">​</a></h2><p>The stock workflow combines:</p><ul><li>business quality;</li><li>valuation context;</li><li>financial resilience;</li><li>technical setup;</li><li>reported fund and insider activity;</li><li>market and portfolio context.</li></ul><p>Use the <a href="/stock-widget">Stock Check Widget</a> to run a company-level research check.</p><h2 id="monitor-market-conditions" tabindex="-1">Monitor Market Conditions <a class="header-anchor" href="#monitor-market-conditions" aria-label="Permalink to &quot;Monitor Market Conditions&quot;">​</a></h2><p>Markets change under the surface. TickerForge helps you review:</p><ul><li>risk-on / risk-off context;</li><li>market stress;</li><li>sector rotation;</li><li>volatility and macro pressure;</li><li>daily and weekly market regime views.</li></ul><p>Open the <a href="/market-widget">Market Regime Widget</a> to compare the latest market views in the browser. For the plain-language framework behind those labels, read <a href="/blog/market-regime-indicators">Market Regime Indicators Explained</a>.</p><h2 id="diagnose-portfolio-health" tabindex="-1">Diagnose Portfolio Health <a class="header-anchor" href="#diagnose-portfolio-health" aria-label="Permalink to &quot;Diagnose Portfolio Health&quot;">​</a></h2><p>TickerForge portfolio tools help users inspect:</p><ul><li>sector concentration;</li><li>top-name concentration;</li><li>cash and exposure;</li><li>market beta sensitivity;</li><li>scenario stress-test estimates;</li><li>portfolio health and structural risk.</li></ul><p>Start with <a href="/portfolio-diagnostics">Portfolio Diagnostics Demo</a> or <a href="/import-portfolio">Import Portfolio</a>.</p><h2 id="use-research-alerts" tabindex="-1">Use Research Alerts <a class="header-anchor" href="#use-research-alerts" aria-label="Permalink to &quot;Use Research Alerts&quot;">​</a></h2><p>TickerForge alerts are monitoring notifications. They can notify you when selected watchlist, portfolio, market-risk, or indicator conditions change.</p><p>Alerts are not instructions to buy or sell. They are designed to bring research changes back to your attention.</p><h2 id="paid-software-features" tabindex="-1">Paid Software Features <a class="header-anchor" href="#paid-software-features" aria-label="Permalink to &quot;Paid Software Features&quot;">​</a></h2><p>Paid plans can unlock software features such as:</p><ul><li>expanded watchlist monitoring limits;</li><li>saved monitoring;</li><li>recurring portfolio diagnostics;</li><li>email and Telegram research notifications;</li><li>exports and advanced analytics views;</li><li>deeper Smart Money and screener workflows.</li></ul><p>Compare access on the <a href="/pricing">Pricing page</a>.</p><h2 id="related-read-next" tabindex="-1">Related / Read Next <a class="header-anchor" href="#related-read-next" aria-label="Permalink to &quot;Related / Read Next&quot;">​</a></h2><ul><li><a href="/demo">See how TickerForge works</a></li><li><a href="/stock-widget">Check a stock</a></li><li><a href="/import-portfolio">Analyze your own portfolio</a></li><li><a href="/portfolio-analysis">Explore portfolio analysis reports</a></li><li><a href="/methodology/">Review the methodology</a></li><li><a href="/use-cases">Browse practical use cases</a></li></ul>',25))])}const v=s(h,[["render",p]]);export{b as __pageData,v as default};
